package com.witchersbestiary.client.book;
import com.witchersbestiary.signs.*;import com.witchersbestiary.client.signs.SignsClient;import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.registry.RegistryWrapper;import net.minecraft.text.Text;import vazkii.patchouli.api.*;import java.util.function.UnaryOperator;
/** A learning page inside the existing bestiary, backed by the single authoritative sign ledger. */
public final class SignLearningComponent implements ICustomComponent {
 public String sign="igni";private int x,y,page;private transient ButtonWidget button;private boolean requested;private SignType type(){return SignType.valueOf(sign.toUpperCase(java.util.Locale.ROOT));}
 public void build(int x,int y,int page){this.x=x;this.y=y;this.page=page;}
 public void onVariablesAvailable(UnaryOperator<IVariable> lookup,RegistryWrapper.WrapperLookup registries){}
 public void onDisplayed(IComponentRenderContext context){button=ButtonWidget.builder(Text.translatable("book.signs.learn"),b->{requested=true;SignsClient.send(2,type().ordinal());}).dimensions(x+8,y+138,98,20).build();context.addWidget(button,page);}
 public void render(DrawContext draw,IComponentRenderContext context,float delta,int mx,int my){var client=MinecraftClient.getInstance();var view=SignsClient.view;boolean known=view!=null&&(view.learned()&(1<<type().ordinal()))!=0;SignsClient.symbol(draw,type(),x+56,y+3,22);draw.drawCenteredTextWithShadow(client.textRenderer,Text.translatable("sign.witchersbestiary."+sign),x+56,y+34,0xff493421);int yy=y+52;for(var line:client.textRenderer.wrapLines(Text.translatable("book.signs.description."+sign).setStyle(context.getFont()),110)){draw.drawText(client.textRenderer,line,x,yy,context.getTextColor(),false);yy+=10;}draw.drawText(client.textRenderer,Text.translatable(known?"book.signs.known":"sign.locked"),x,y+100,known?0xff31582d:0xff75522c,false);if(button!=null){button.active=view!=null&&!known;button.setMessage(Text.translatable(known?"book.signs.known":"book.signs.learn"));}if(known&&requested){requested=false;yy=y+141;var menu=java.util.Arrays.stream(client.options.allKeys).filter(k->k.getTranslationKey().equals("key.witchersbestiary.sign_menu")).findFirst().orElseThrow();var cast=java.util.Arrays.stream(client.options.allKeys).filter(k->k.getTranslationKey().equals("key.witchersbestiary.sign_cast")).findFirst().orElseThrow();client.player.sendMessage(Text.translatable("book.signs.controls",menu.getBoundKeyLocalizedText(),cast.getBoundKeyLocalizedText()),true);}}
}
